      val (fa, fsp, _) = first
      val (ga, gsp, _) = second
      val b1 = fsp == gsp
      val b2 = (fsp == gsp) &&
      signatures.exists(third => third match {
           case (ha, hsp, _) => {
              val a1 = (hsp == fsp) 
              val a2 = a1 && oa.lteq(ha, fa) 
