#!/usr/bin/env python3
"""Probe: from DeclScan's table, every trait or object T that provides an abstract method
declaration and a body of the same name, self position and parameter types (without self,
static arguments put in), from two declaring types neither of which is below the other's
... (row 572's shape: the body's type not below the abstract one's), and that declares none
of its own. Provided is computed as traits.tex:571-581 says: what T declares, and what its
immediate supertypes provide except a declaration whose parameter types (self apart) equal
those of one T declares. Also lists two abstract declarations from unrelated types, and two
bodies from unrelated types, met in T with none of its own."""
import sys, re, collections

rows = [l.rstrip('\n').split('\t') for l in open(sys.argv[1]) if l[0] in 'TM']
COMPILER = re.compile(r'(^|/)(Compiler(Builtin|Library|Algebra|System))\.fs[is]$')

def world(f):
    if COMPILER.search(f): return 'compiler'
    if f.endswith('/AnyType.fsi') or f.endswith('/AnyType.fss'): return 'both'
    if '/incomplete/' in f: return 'incomplete'
    return 'interp'

def stem(f): return re.sub(r'\.fs[is]$', '', f)

# declarations: per (stem, name), prefer the component's (.fss) to the api's (.fsi)
decls = {}      # (stem, name) -> dict
for r in rows:
    if r[0] == 'T':
        _, f, line, kind, name, sp, ex = r
        key = (stem(f), name)
        d = {'file': f, 'line': int(line), 'kind': kind, 'name': name, 'sparams': [s for s in sp.split(',') if s],
             'extends': [e for e in ex.split(';') if e], 'methods': [], 'world': world(f)}
        old = decls.get(key)
        if old is None or (old['file'].endswith('.fsi') and f.endswith('.fss')):
            decls[key] = d
            d['methods_from'] = f
for r in rows:
    if r[0] == 'M':
        _, f, line, owner, name, self, params, ret, body, mods, msp = (r + [''] * 11)[:11]
        d = decls.get((stem(f), owner))
        if d is None or d['methods_from'] != f: continue
        d['methods'].append({'file': f, 'line': int(line), 'name': name, 'self': int(self), 'params': params,
                             'ret': ret, 'body': body == 'body', 'getter': 'getter' in mods or 'setter' in mods,
                             'override': 'override' in mods, 'own_sparams': [s for s in msp.split(',') if s]})

byname = collections.defaultdict(list)
for (st, name), d in decls.items(): byname[name].append((st, d))
PRELUDE = ('FortressLibrary', 'FortressBuiltin', 'AnyType')

def split_args(s):
    out, depth, cur = [], 0, ''
    i = 0
    while i < len(s):
        if s.startswith('[\\', i): depth += 1; cur += '[\\'; i += 2; continue
        if s.startswith('\\]', i): depth -= 1; cur += '\\]'; i += 2; continue
        c = s[i]
        if c in '([': depth += 1
        if c in ')]': depth -= 1
        if c == ',' and depth == 0: out.append(cur.strip()); cur = ''
        else: cur += c
        i += 1
    if cur.strip(): out.append(cur.strip())
    return out

def parse_type(t):
    m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)(?:\[\\(.*)\\\])?$', t.strip())
    if not m: return None, []
    return m.group(1), split_args(m.group(2)) if m.group(2) else []

def resolve(name, from_d):
    cands = [(st, d) for st, d in byname.get(name, []) if d['world'] in (from_d['world'], 'both')
             or (from_d['world'] == 'both')]
    if not cands: return None, 'unresolved'
    own = [c for c in cands if c[0] == stem(from_d['file'])]
    if own: return own[0][1], ''
    if len(cands) == 1: return cands[0][1], ''
    pre = [c for c in cands if c[0].split('/')[-1] in PRELUDE]
    if len(pre) == 1: return pre[0][1], ''
    return cands[0][1], 'ambiguous:' + ','.join(c[0] for c in cands)

def subst(text, mapping):
    if not mapping: return text
    return re.sub(r'\b[A-Za-z_][A-Za-z0-9_]*\b', lambda m: mapping.get(m.group(0), m.group(0)), text)

def norm(s): return re.sub(r'\s+', '', s)

notes = collections.Counter()
memo = {}
def provided(d, mapping_key=()):
    """the methods d provides, each (method, owner decl, substitution text of params, ret)"""
    key = (id(d), mapping_key)
    if key in memo: return memo[key]
    memo[key] = []
    mapping = dict(mapping_key)
    own = [(m, d, subst(m['params'], mapping), subst(m['ret'], mapping)) for m in d['methods']]
    res = list(own)
    for e in d['extends']:
        e2 = subst(e, mapping)
        n, args = parse_type(e2)
        if n is None: notes['unparsed extends'] += 1; continue
        sd, why = resolve(n, d)
        if sd is None: notes['unresolved ' + n] += 1; continue
        if why: notes[why] += 1
        mk = tuple(zip(sd['sparams'], args)) if len(args) == len(sd['sparams']) else ()
        for (m, o, p, r) in provided(sd, mk):
            if any(om['name'] == m['name'] and om['self'] == m['self'] and norm(op) == norm(p)
                   for (om, _, op, _) in own):
                continue    # a declaration of d's own at the same parameter types
            if not any(x[0] is m and norm(x[2]) == norm(p) for x in res):
                res.append((m, o, p, r))
    memo[key] = res
    return res

anc_memo = {}
def ancestors(d):
    if id(d) in anc_memo: return anc_memo[id(d)]
    anc_memo[id(d)] = set()
    res = {id(d)}
    for e in d['extends']:
        n, _ = parse_type(e)
        if n is None: continue
        sd, _ = resolve(n, d)
        if sd is not None: res |= ancestors(sd)
    anc_memo[id(d)] = res
    return res

def below(x, y): return id(y) in ancestors(x)

out = collections.defaultdict(list)
for (st, name), d in sorted(decls.items(), key=lambda kv: (kv[1]['file'], kv[1]['line'])):
    if d['world'] == 'incomplete': continue
    groups = collections.defaultdict(list)
    for (m, o, p, r) in provided(d, tuple((s, s) for s in d['sparams'])):
        groups[(m['name'], m['self'], norm(p))].append((m, o, p, r))
    for (mname, self, p), ms in groups.items():
        if len(ms) < 2: continue
        if any(o is d for (_, o, _, _) in ms): continue      # d declares one of its own
        abst = [x for x in ms if not x[0]['body']]
        conc = [x for x in ms if x[0]['body']]
        for a in abst:
            for c in conc:
                if c[1] is a[1] or below(c[1], a[1]): continue
                out['572'].append((d, mname, self, p, a, c))
        for i, a in enumerate(abst):
            for b in abst[i+1:]:
                if a[1] is b[1] or below(a[1], b[1]) or below(b[1], a[1]): continue
                out['two-abstract'].append((d, mname, self, p, a, b))
        for i, a in enumerate(conc):
            for b in conc[i+1:]:
                if a[1] is b[1] or below(a[1], b[1]) or below(b[1], a[1]): continue
                out['two-bodies'].append((d, mname, self, p, a, b))
    # row 727's shape: one declaration declares one name twice at the same parameter types, one abstract
    seen = collections.defaultdict(list)
    for m in d['methods']:
        seen[(m['name'], m['self'], norm(m['params']))].append(m)
    for k, ms in seen.items():
        if len(ms) > 1 and any(not m['body'] for m in ms) and any(m['body'] for m in ms):
            out['727'].append((d, k, ms))

def loc(m): return '%s:%d' % (m['file'], m['line'])
for kind in ('572', 'two-abstract', 'two-bodies'):
    print('## %s: %d' % (kind, len(out[kind])))
